13: function calculateQuote(nightlyPrice, startDateStr, endDateStr) {
14:   if (!startDateStr || !endDateStr) {
15:     return { error: 'Missing start or end date' };
16:   }
17:   const start = new Date(startDateStr);
18:   const end = new Date(endDateStr);
19:   
20:   if (isNaN(start.getTime()) || isNaN(end.getTime())) {
21:     return { error: 'Invalid date format' };
22:   }
23:   
24:   // Normalize dates to remove timezone variations for diff calculations
25:   const dStart = new Date(start.getFullYear(), start.getMonth(), start.getDate());
26:   const dEnd = new Date(end.getFullYear(), end.getMonth(), end.getDate());
27:   
28:   if (dStart >= dEnd) {
29:     return { error: 'Start date must be before end date' };
30:   }
31:   
32:   const diffTime = dEnd - dStart;
33:   const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
34:   
35:   const totalPrice = diffDays * nightlyPrice;
36:   return {
37:     nights: diffDays,
38:     nightlyPrice,
39:     totalPrice: parseFloat(totalPrice.toFixed(2))
40:   };
41: }
