"const fs = require('fs');
const path = require('path');

const filePath = process.argv[2];
let findArg = process.argv[3];
let replaceArg = process.argv[4];

if (!filePath || findArg === undefined || replaceArg === undefined) {
  console.error("Usage: node patcher.js <file> <find_text_or_@file> <replace_text_or_@file>");
  process.exit(1);
}

const fullPath = path.resolve(filePath);

let findStr = findArg;
if (findArg.startsWith('@')) {
  findStr = fs.readFileSync(path.resolve(findArg.substring(1)), 'utf8');
}

let replaceStr = replaceArg;
if (replaceArg.startsWith('@')) {
  replaceStr = fs.readFileSync(path.resolve(replaceArg.substring(1)), 'utf8');
}

let content = fs.readFileSync(fullPath, 'utf8');
if (!content.includes(findStr)) {
  console.error(`Error: Could not find target text in ${fullPath}`);
  process.exit(1);
}

content = content.replace(findStr, replaceStr);
fs.writeFileSync(fullPath, content, 'utf8');
console.log(`Patched ${filePath} successfully.`);
"

